from csvutil import to_csv_row


def test_plain_fields_stay_bare():
    assert to_csv_row(['a', 'b', 'c']) == 'a,b,c'


def test_comma_triggers_quoting():
    assert to_csv_row(['a,b', 'c']) == '"a,b",c'


def test_embedded_quote_is_doubled_and_quoted():
    assert to_csv_row(['say "hi"']) == '"say ""hi"""'


def test_newline_triggers_quoting():
    assert to_csv_row(['line1\nline2']) == '"line1\nline2"'


def test_mixed_row():
    row = to_csv_row(['plain', 'has,comma', 'has"quote'])
    assert row == 'plain,"has,comma","has""quote"'

