def _escape_field(field):
    needs_quoting = ',' in field or '"' in field or '\n' in field
    if not needs_quoting:
        return field
    escaped = field.replace('"', '""')
    return f'"{escaped}"'


def to_csv_row(fields):
    return ','.join(_escape_field(f) for f in fields)

